// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// Vertex attributes
attribute vec3 aPosition;
attribute vec2 aTexCoord;

// Pass-through to the fragment shader
varying vec2 vTexCoord;

void main() {
    // Pass texture coordinates to the fragment shader
    vTexCoord = aTexCoord;

    // Transform the position into normalized device coordinates (NDC)
    vec4 positionVec4 = vec4(aPosition, 1.0);

    // Scale and shift to NDC (Normalize Device Coordinate) range [-1, 1]
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

    // Set the final position of the vertex
    gl_Position = positionVec4;
}


// === Tab: fragment.glsl ===
/*
 * You can use this as a template to make shaders! Have fun!
 */

// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// These are our passed in information from the sketch.js
uniform vec2 iResolution;
uniform float iTime;
//uniform vec2 iMouse;

varying vec2 vTexCoord;

// See Art of Code: Hexagonal Tiling Explained!
// https://www.youtube.com/watch?v=VmrIDyYiJBA

float HexDist(vec2 p){
    p = abs(p);
    float c = dot(p, normalize(vec2(1, 1.73)));
    c= max(c,p.x);
    return c;
}

vec4 HexCoord(vec2 uv){
    vec2 r = vec2(1, 1.73);
    vec2 h = r * 0.5;
    vec2 a = mod(uv, r) - h;
    vec2 b = mod(uv - h, r) - h;

    vec2 gv;
    if(length(a) < length(b))
        gv = a;
    else 
        gv = b;

    float x = atan(gv.x, gv.y);
		float y = 0.5 - HexDist(gv);
    vec2 id = uv - gv;
    return vec4(x, y, id.x, id.y);
}

float pattern(vec2 uv, float t){
   float speed = 0.25;
	 return sin(dot(uv, uv) + t * speed);
}


void main() {
    // Map vTexCoord to normalized device coordinates (NDC) [-1, 1]
    vec2 uv = vTexCoord * 2.0 - 1.0;

    // Define a scale factor
    const float scale = 1.0;

    // Adjust for aspect ratio and scale the coordinates
    uv.x *= scale * iResolution.x / iResolution.y;
    uv.y *= scale;

    vec3 col = vec3(0.0);

    uv *= 10.0;

    vec4 hc = HexCoord(uv);

		// Thanks to Fabrice Neyret for advice :)
    float v =  hc.y * pattern(vec2(hc.z, hc.w), iTime) - 0.035;

    float c = smoothstep(0.0, 25.0/iResolution.y * 0.5, v ); 
    col += c;

		//col.gb = HexCoord(hc).xy*0.2;

    // Output the final color with full opacity
    gl_FragColor = vec4(col, 1.0);
}

